// src/api/partStockAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

const host = apiPath("/stock/partstocks");

// 전체 리스트
export const getPartStockList = async () => {
  const { data } = await axios_api.get(host);
  return data; // PartStockResponseDto[]
};

// 단건(필요하면)
export const getPartStockOne = async (stockNo) => {
  const { data } = await axios_api.get(apiPath(`/stock/partstocks/${stockNo}`));
  return data;
};

// 재고 수동추가/입고반영(필요하면)
export const addPartStock = async ({ buyerComp, partName, stockQty, partPrice }) => {
  const payload = {
    buyerComp: String(buyerComp || ""),
    partName: String(partName || ""),
    stockQty: Number(stockQty || 0),
    partPrice: Number(partPrice || 0),
  };
  const { data } = await axios_api.post(host, payload);
  return data;
};
